import java.io.IOException;

/**
 * I have made the SyntaxAnalyser class implement a recursive descent parser by extending 
 * AbstractSyntaxAnalyser to process the tokens generated by the LexicalAnalyser.
 * The parser's job is to verify whether the source programs conform to the grammar and call methods
 * I have designed it in a way that when a syntax error is detected, a
 * CompilationException is thrown after logging an appropriate error message.
 */

public class SyntaxAnalyser extends AbstractSyntaxAnalyser {

    /**
     * I have designed the constructor to set up the LexicalAnalyser with the provided source file name
     * and have also assigned the filename to the Generate class so that I can show which file the errors corresponds to.
     * @param fileName the name of the file containing the source program.
     * @throws IOException if there is an error reading the file.
     */

    public SyntaxAnalyser(String fileName) throws IOException {

        // I am just initialising the Lexical Analyser with the source file. 
        this.lex = new LexicalAnalyser(fileName);
        
        // I am storing the file name so that I can make use of it to show which program files the errors belong to.
        Generate.fileName = fileName;
    }

    /**
     * The idea is to parse the <StatementPart> nonterminal.
     * The Grammar: <StatementPart> ::= begin <StatementList> end
     *
     * I designed this method so that it expects the 'begin' token, then calls _statementList_() to parse the list
     * of statements, and finally expects the 'end' token.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    @Override
    public void _statementPart_() throws IOException, CompilationException {

        // Here, I am capturing the current line number so that I can report which line the error corresponds to.
        int lineNo = nextToken.lineNumber;

        // Let us consider and log this the start of the <StatementPart>
        myGenerate.commenceNonterminal("StatementPart");
        try {

            // Now, I am expecting and consuming the "begin" token.
            acceptTerminal(Token.beginSymbol);

            // I am updating the line number after I consume the token.
            lineNo = nextToken.lineNumber;

            // Parse the <StatementList> nonterminal.
            _statementList_();

            // Again, I am updating the line number.
            lineNo = nextToken.lineNumber;

            // Now, I am expecting and consuming the "end" token.
            acceptTerminal(Token.endSymbol);

            // Again, I am updating the line number.
            lineNo = nextToken.lineNumber;
        } catch (CompilationException ce) {

            // Now, I am wrapping and throwing the exception indicating the user where the error was made and indicating the grammar.
            throw new CompilationException("Syntax Error when parsing (StatementPart) -> Expected {begin <StatementList> end} on line: " + lineNo, ce);
        }

        // This logs the end of my <StatementPart>.
        myGenerate.finishNonterminal("StatementPart");
    }

    /**
     * The idea is to parse the <StatementList> nonterminal.
     * The Grammar: <StatementList> ::= <Statement> | <StatementList> ; <Statement>
     *
     * I designed this method to recursively parses one statement and, if a semicolon is encountered, continues
     * to parse additional statements.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _statementList_() throws IOException, CompilationException {

        // My first task is to log the current line number.
        int lineNo = nextToken.lineNumber;

        // Then I log the start of <StatementList>.
        myGenerate.commenceNonterminal("StatementList");
        try {

            // Then I start by parsing a single statement.
            _statement_();

            // Then I see if the next token is a semicolon or not. If so, I accept it and recursively parse the next statement.
            if (nextToken.symbol == Token.semicolonSymbol) {
                lineNo = nextToken.lineNumber;
                acceptTerminal(Token.semicolonSymbol);
                lineNo = nextToken.lineNumber;
                _statementList_();
            }
        } catch (CompilationException ce) {

            // Then I wrap and throw exception with context for statement list parsing.
            throw new CompilationException("Syntax Error when parsing (StatementList) -> Expected {<Statement> | <StatementList> ; <Statement>} on line: " + lineNo, ce);
        }
        myGenerate.finishNonterminal("StatementList");
    }

    /**
     * The idea is to parse the <Statement> nonterminal.
     * Grammar: <Statement> ::= <AssignmentStatement> | <IfStatement> | <WhileStatement> |
     *                           <ProcedureStatement> | <UntilStatement> | <ForStatement>
     *
     * I designed this method to use the current token (lookahead) to decide which statement type to parse.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */
    private void _statement_() throws IOException, CompilationException {

        // My first task is to log the current line number.
        int lineNo = nextToken.lineNumber;

        // Then I log the start of a Statement
        myGenerate.commenceNonterminal("Statement");
    
        try {

            // The idea is to decide which statement to parse based on the current token.
            switch (nextToken.symbol) {
                case Token.identifier:
                    _assignmentStatement_();    // Parse an assignment statement.
                    break;
                case Token.callSymbol:
                    _procedureStatement_();     // Parse a procedure call
                    break;
                case Token.whileSymbol:
                    _whileStatement_();         // Parse a while loop.
                    break;
                case Token.ifSymbol:
                    _ifStatement_();            // Parse an if statement.
                    break;
                case Token.doSymbol:
                    _untilStatement_();         // Parse an until statement.
                    break;
                case Token.forSymbol:
                    _forStatement_();           // Parse a for loop.
                    break;
                default:

                    // If the token DOES NOT match any expected type, I report an error.
                    myGenerate.reportError(nextToken, "Unexpected token. Expected a statement.");
                    break;
            }
        } catch (CompilationException ce) {

            // I then wrap the error with context about what was expected in a statement.
            throw new CompilationException("Syntax Error when parsing (Statement) -> Expected {<AssignmentStatement> | <IfStatement> | <WhileStatement> etc.} on line: " + lineNo, ce);
        }
        
        // I then log the end of a statement.
        myGenerate.finishNonterminal("Statement");
    }    

    /**
     * The idea is to parse the <IfStatement> nonterminal.
     * Grammar:<IfStatement> ::= if <Condition> then <StatementList> end if |
     *                           if <Condition> then <StatementList> else <StatementList> end if
     *
     * I designed this method to check for the 'if' keyword, condition, 'then', statement list, optional 'else'
     * part, and finally the 'end if' terminator.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _ifStatement_() throws IOException, CompilationException {

        // I again start by logging the line number.
        int lineNo = nextToken.lineNumber;

        // Then I go ahead and log the start of my <IfStatement>.
        myGenerate.commenceNonterminal("IfStatement");

        try {

            // First, I accept the "if" keyword.
            acceptTerminal(Token.ifSymbol);

            // Then I go and log the updated line number.
            lineNo = nextToken.lineNumber;
            
            // I parse the condition and expect an identifier to begin the condition.
            if (nextToken.symbol == Token.identifier) {
                _condition_();
                lineNo = nextToken.lineNumber;  // I log the updated line number.
            } else {
                myGenerate.reportError(nextToken, "Expected a condition in 'if' statement.");
            }
            
            // I check is there a "then" keyword after the condition.
            if (nextToken.symbol == Token.thenSymbol) {
                acceptTerminal(Token.thenSymbol);   // If so, I accept it.
                lineNo = nextToken.lineNumber;      // And log the updated line number.
            } else {
                myGenerate.reportError(nextToken, "Missing 'then' after condition.");
            }

            // Then I move forward to parse the statement list for the 'if' branch.
            _statementList_();
            lineNo = nextToken.lineNumber;

            // In this part, I am checking for an "else" branch.
            if (nextToken.symbol == Token.elseSymbol) {
                acceptTerminal(Token.elseSymbol);   // If found, I accept it,
                lineNo = nextToken.lineNumber;      // log the updated line number.

                _statementList_();      // Go ahead and parse the statement list for "else" branch.
                lineNo = nextToken.lineNumber;      // log the updated line number.
            }

            // Finally, I check is the next token an "end", and then check if the 'if' token is properly closed.
            if (nextToken.symbol == Token.endSymbol) {
                acceptTerminal(Token.endSymbol);    // If so, I accept the "end" token.
                lineNo = nextToken.lineNumber;      // Log the updated line number.

                if (nextToken.symbol == Token.ifSymbol) {
                    acceptTerminal(Token.ifSymbol);
                    lineNo = nextToken.lineNumber;
                } else {
                    myGenerate.reportError(nextToken, "Missing 'if' after 'end' in 'if' statement.");
                }
            } else {
                myGenerate.reportError(nextToken, "Expected 'end if' to close 'if' statement.");
            }
        } catch (CompilationException ce) {

            // I then wrap the error with context about what was expected in a If Statement.
            throw new CompilationException("Syntax Error when parsing (IfStatement) -> Expected {if <Condition> then <StatementList> end if | if <Condition> then <StatementList> else <StatementList> end if} on line: " + lineNo, ce);
        }

        // Finally, I log the end of the If Statement.
        myGenerate.finishNonterminal("IfStatement");
    }
    

    /**
     * The idea is to parse the <UntilStatement> nonterminal.
     * Grammar: <UntilStatement> ::= do <StatementList> until <Condition>
     *
     * I designed this method to expect a 'do' token, a statement list, an 'until' token, and finally a condition.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */
    private void _untilStatement_() throws IOException, CompilationException {

        // I am saving the current line number for error reporting.
        int lineNo = nextToken.lineNumber;

        // I am logging the start of <UntilStatement>.
        myGenerate.commenceNonterminal("UntilStatement");

        try {

            // I then accept the 'do' keyword.
            acceptTerminal(Token.doSymbol);

            // Go on to update the line number.
            lineNo = nextToken.lineNumber;

            // Then I parse the statement list that comes after 'do'.
            _statementList_();

            // I am updating the line number after the statement list.
            lineNo = nextToken.lineNumber;

            // Then I accept the 'until' keyword.
            acceptTerminal(Token.untilSymbol);

            // I go and update the line number after accepting "until".
            lineNo = nextToken.lineNumber;

            // Then I check if the next token starts a condition. If it is an identifier, I parsed the condition.
            if (nextToken.symbol == Token.identifier) {
                _condition_();
            } else {

                // Else, I report an error because the condition is missing.
                myGenerate.reportError(nextToken, "First argument condition for until is missing");
            }
        } catch (CompilationException ce) {

            // I wrap and throw the exception with context about what I expected.
            throw new CompilationException("Syntax Error when parsing (UntilStatement) -> Expected {do <StatementList> until <Condition>} on line: " + lineNo, ce);
        }

        // Finally, I am logging the end of <UntilStatement>.
        myGenerate.finishNonterminal("UntilStatement");
    }

    /**
     * My logic is to parse the <ForStatement> nonterminal.
     * 
     * Grammar: <ForStatement> ::= for ( <AssignmentStatement> ; <Condition> ; <AssignmentStatement> ) do <StatementList> end loop
     *
     * The method is designed to check for the 'for' keyword, the proper parenthesized structure with initialisation,
     * condition, update assignment, the 'do' keyword, a statement list, and finally the proper termination
     * with 'end loop'.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */
    private void _forStatement_() throws IOException, CompilationException {

        // I am capturing the current line number.
        int lineNo = nextToken.lineNumber;

        // I am logging the start of <ForStatement>.
        myGenerate.commenceNonterminal("ForStatement");

        try {

            // I accept the 'for' keyword.
            acceptTerminal(Token.forSymbol);

            // I update the line number.
            lineNo = nextToken.lineNumber;

            // I am checking for the opening parenthesis '('.
            if (nextToken.symbol == Token.leftParenthesis) {
                acceptTerminal(Token.leftParenthesis);  // I accept the left parenthesis.
                lineNo = nextToken.lineNumber;  // I update the line number.
            } else {

                // If not found, I report a message indicating '(' is missing.
                myGenerate.reportError(nextToken, "Missing '(' at the beginning of 'for' statement.");
                return;
            }

            // I parse the initialisation assignment.
            _assignmentStatement_();

            // After assignment, I update the line number.
            lineNo = nextToken.lineNumber;

            // I now expect and accept a semicolon after the initialisation.
            if (nextToken.symbol == Token.semicolonSymbol) {
                acceptTerminal(Token.semicolonSymbol);

                // I then update the line number after the semicolon.
                lineNo = nextToken.lineNumber;
            } else {

                // If not found, I report an error because the semicolon is missing.
                myGenerate.reportError(nextToken, "Expected ';' after initialization in 'for' statement.");
                return;
            }

            // I parse the condition part of the for loop.
            _condition_();

            // I then update the line number after the condition.
            lineNo = nextToken.lineNumber;

            // I now expect and accept another semicolon after the condition.
            if (nextToken.symbol == Token.semicolonSymbol) {
                acceptTerminal(Token.semicolonSymbol);

                // I then update the line number after the semicolon.
                lineNo = nextToken.lineNumber;
            } else {

                // If not found, I report an error because the semicolon after the condition is missing.
                myGenerate.reportError(nextToken, "Expected ';' after condition in 'for' statement.");
                return;
            }

            // Now, I parse the update assignment.
            _assignmentStatement_();

            // I then update the line number after the  the update assignment.
            lineNo = nextToken.lineNumber;

            // Now, I check, expect and accept the closing parenthesis ')'
            if (nextToken.symbol == Token.rightParenthesis) {
                acceptTerminal(Token.rightParenthesis);
                lineNo = nextToken.lineNumber;  // I update the line number after the closing parenthesis.
            } else {

                // Else, I report an error because the closing parenthesis is missing.
                myGenerate.reportError(nextToken, "Missing ')' in 'for' statement.");
                return;
            }

            // Now, I expect and accept the 'do' keyword that starts the loop body.
            if (nextToken.symbol == Token.doSymbol) {
                acceptTerminal(Token.doSymbol);

                // I update the line number after 'do'.
                lineNo = nextToken.lineNumber;
            } else {

                // Else, I report an error because the 'do' keyword is missing.
                myGenerate.reportError(nextToken, "Expected 'do' keyword in 'for' statement.");
                return;
            }

            // I go ahead to parse statement list that makes up the loop body.
            _statementList_();

            // Then, I update the line number after the statement list.
            lineNo = nextToken.lineNumber;

            // After that I check for the closing tokens to finish the for loop.
            switch (nextToken.symbol) {
                case Token.endSymbol:
                    acceptTerminal(Token.endSymbol);

                    // Now, I update the line number after 'end'.
                    lineNo = nextToken.lineNumber;

                    if (nextToken.symbol == Token.loopSymbol) {
                        acceptTerminal(Token.loopSymbol);
                        lineNo = nextToken.lineNumber;  // I update the line number after 'loop'.
                    } else {

                        // I report an error because 'loop' was expected after 'end'.
                        myGenerate.reportError(nextToken, "Expected 'loop' after 'end' to close 'for' statement.");
                    }
                    break;
                default:
                    // After that I report an error because I expected the closing tokens for the loop.
                    myGenerate.reportError(nextToken, "Expected 'end loop' to close 'for' statement.");
            }

        } catch (CompilationException ce) {
            // Finally, I wrap and throw the exception with context for the for statement.
            throw new CompilationException("Syntax Error when parsing (ForStatement) -> Expected {for (<AssignmentStatement>; <Condition>; <AssignmentStatement>) do <StatementList> end loop} on line: " + lineNo, ce);
        }

        myGenerate.finishNonterminal("ForStatement");
    }

    /**
     * My logic is to parse the <AssignmentStatement> nonterminal.
     * Grammar: <AssignmentStatement> ::= identifier := <Expression> | identifier := stringConstant
     *
     * I designed it to expect an identifier, followed by the becomes symbol (':='), and then either an expression
     * or a string constant.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _assignmentStatement_() throws IOException, CompilationException {

        // I capture the current line number.
        int lineNo = nextToken.lineNumber;

        // I log the start of <AssignmentStatement>.
        myGenerate.commenceNonterminal("AssignmentStatement");
        try {

            // I expect and accept an identifier at the start.
            acceptTerminal(Token.identifier);

            // I update the line number after 'identifier'.
            lineNo = nextToken.lineNumber;

            // I expect and accept the assignment operator ':='.
            acceptTerminal(Token.becomesSymbol);

            // I update the line number after operator.
            lineNo = nextToken.lineNumber;

            // Depending on the next token, I either accept a string constant or parse an expression.
            if (nextToken.symbol == Token.stringConstant) {
                acceptTerminal(Token.stringConstant);

                // I update the line number after the string constant.
                lineNo = nextToken.lineNumber;
            } else {
                _expression_();

                // I update the line number after the expression.
                lineNo = nextToken.lineNumber;
            }

        } catch (CompilationException ce) {

            // I wrap and rethrow the exception with context for assignment statements.
            throw new CompilationException("Syntax Error when parsing (AssignmentStatement) -> Expected {<identifier> := <expression> | <identifier> := <stringConstant>} on line: " + lineNo, ce);
        }

        // Finally, I log the end of <AssignmentStatement>.
        myGenerate.finishNonterminal("AssignmentStatement");
    }

     /**
     * My logic is to parse <ProcedureStatement> nonterminal.
     * Grammar: <ProcedureStatement> ::= call identifier ( <ArgumentList> )
     *
     * I designed it to expect a 'call' keyword, a procedure identifier, and optionally an argument list enclosed
     * in parentheses.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _procedureStatement_() throws IOException, CompilationException {

        // Again, I start by logging the current line number
        int lineNo = nextToken.lineNumber;
        
        // Then I log the start of <ProcedureStatement>.
        myGenerate.commenceNonterminal("ProcedureStatement");
        
        try {

            // I advance by accepting the 'call' keyword.
            acceptTerminal(Token.callSymbol);

            // I update the line number after 'call'.
            lineNo = nextToken.lineNumber;

            // Then I check if the next token is a valid procedure identifier.
            if (nextToken.symbol != Token.identifier) {
                myGenerate.reportError(nextToken, "Expected a procedure identifier after 'call'.");
                return;
            }
            acceptTerminal(Token.identifier);   // Else, I accept the procedure identifier.
            lineNo = nextToken.lineNumber;      // and, update the line number after accepting the identifier.

            // Now, I check for an argument list. If found, it must be enclosed in parentheses.
            if (nextToken.symbol == Token.leftParenthesis) {

                // I go ahead accepting the left parenthesis.
                acceptTerminal(Token.leftParenthesis);

                // After which I update the line number.
                lineNo = nextToken.lineNumber;

                // I then parse the argument list
                _argumentList_();

                // and update the line number after parsing the argument list.
                lineNo = nextToken.lineNumber;

                // Towards the end, I am checking for a right/closing parenthesis of the argument list.
                if (nextToken.symbol == Token.rightParenthesis) {
                    acceptTerminal(Token.rightParenthesis);

                    // I update the line number after the ')'.
                    lineNo = nextToken.lineNumber;
                } else {

                    // If I could not find the closing ')', I report an error.
                    myGenerate.reportError(nextToken, "Missing ')' to close argument list.");
                }
            }
        } catch (CompilationException ce) {

            // I wrap and throw the exception with context for procedure statements.
            throw new CompilationException("Syntax Error when parsing (ProcedureStatement) -> Expected {call <identifier> (<ArgumentList>)} on line: " + lineNo, ce);
        }

        // And finish by logging the end of <ProcedureStatement>.
        myGenerate.finishNonterminal("ProcedureStatement");
    }

    /**
     * My logic is to parse the <WhileStatement> nonterminal.
     * Grammar: <WhileStatement> ::= while <Condition> loop <StatementList> end loop
     *
     * I designed it to expect the 'while' keyword, a condition, the 'loop' keyword, a statement list for the loop
     * body, and finally the termination sequence 'end loop'.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _whileStatement_() throws IOException, CompilationException {

        // Again, I start by logging the current line number
        int lineNo = nextToken.lineNumber;

        // I log the start of <WhileStatement>.
        myGenerate.commenceNonterminal("WhileStatement");
        try {

            // I accept the 'while' keyword.
            acceptTerminal(Token.whileSymbol);

            // Then update the line number after 'while'.
            lineNo = nextToken.lineNumber;

            // I check if a valid condition follows; if not, I report an error.
            if (nextToken.symbol != Token.identifier) {
                myGenerate.reportError(nextToken, "Expected a valid condition after 'while'.");
                return;
            }

            // Parse the condition,
            _condition_();

            // and update the line number after the condition.
            lineNo = nextToken.lineNumber;

            // I expect the 'loop' keyword to mark the start of the loop body.
            switch (nextToken.symbol) {
                case Token.loopSymbol:
                    acceptTerminal(Token.loopSymbol);
                    break;
                default:

                    // Else, I report an error because a "loop" was expected.
                    myGenerate.reportError(nextToken, "Expected 'loop' to start while block.");
                    return;
            }

            lineNo = nextToken.lineNumber;  // I update the line number after the "loop"
            _statementList_();              // Start parsing the statement list that forms the body of the loop.
            lineNo = nextToken.lineNumber;  // Update the line number after the statement list. 

            // This design of mine expects the closing tokens 'end' followed by 'loop' to finish the while loop.
            switch (nextToken.symbol) {
                case Token.endSymbol:
                    acceptTerminal(Token.endSymbol);
                    lineNo = nextToken.lineNumber;  // I update the line number after 'end'.
                    if (nextToken.symbol == Token.loopSymbol) {
                        acceptTerminal(Token.loopSymbol);
                    } else {

                        // I report an error because 'loop' is expected after 'end'.
                        myGenerate.reportError(nextToken, "Expected 'loop' after 'end' to close while block.");
                    }
                    break;
                default:

                    // I report an error because the closing 'end loop' is expected.
                    myGenerate.reportError(nextToken, "Expected 'end loop' to close while block.");
            }

            // I update the line number after closing the loop.
            lineNo = nextToken.lineNumber;
        } catch (CompilationException ce) {

            // I wrap and throw the exception with context for the while statement.
            throw new CompilationException("Syntax Error when parsing (WhileStatement) -> Expected {while <Condition> loop <StatementList> end loop} on line: " + lineNo, ce);
        }

        myGenerate.finishNonterminal("WhileStatement");
    }

    /**
     * Parses the <Expression> nonterminal.
     * Grammar: <Expression> ::= <Term> | <Expression> + <Term> | <Expression> - <Term>
     *
     * It is designed to parse a term, then checks for '+' or '-' operators to decide if it should
     * recursively parse an extended expression.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    public void _expression_() throws IOException, CompilationException {

        // I record the current line number.
        int lineNo = nextToken.lineNumber;

        // Then, I log the start of <Expression>.
        myGenerate.commenceNonterminal("Expression");

        try {

            // Parse the first term of the expression.
            _term_();

            // Then I check if the next token is '+' or '-' to extend the expression.
            switch (nextToken.symbol) {
                case Token.plusSymbol:
                case Token.minusSymbol:

                    // Accept the operator.
                    acceptTerminal(nextToken.symbol);

                     // I update the line number after the operator.
                    lineNo = nextToken.lineNumber;

                    // Recursively parse the rest of the expression.
                    _expression_();
                    break;
                default:

                    // And do nothing if there is no additional operator.
                    break;
            }
        } catch (CompilationException ce) {

            // I wrap and throw the exception with context for the expression.
            throw new CompilationException("Syntax Error when parsing (Expression) -> Expected {<Term> | <Expression> + <Term> | <Expression> - <Term>} on line: " + lineNo, ce);
        }

        // Finally, I log the end of <Expression>.
        myGenerate.finishNonterminal("Expression");
    }

    /**
     * My logic is to parse the <Term> nonterminal.
     * Grammar: <Term> ::= <Factor> | <Term> * <Factor> | <Term> / <Factor> | <Term> % <Factor>
     *
     * It starts by parsing a factor, and if a multiplicative operator is present, accepts the
     * operator and recursively parses the remaining term.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    public void _term_() throws IOException, CompilationException {

        // I record the current line number.
        int lineNo = nextToken.lineNumber;

        // I log the start of <Term>.
        myGenerate.commenceNonterminal("Term");
        
        try {

            // Parse the initial factor of the term.
            _factor_();

            // I check if the next token is an operator (*, /, or %).
            boolean isMultiplicativeOperator = (nextToken.symbol == Token.timesSymbol ||
                    nextToken.symbol == Token.divideSymbol ||
                    nextToken.symbol == Token.modSymbol);

            // If so, I accept the operator.
            if (isMultiplicativeOperator) {
                acceptTerminal(nextToken.symbol);

                // Update the line number after the operator.
                lineNo = nextToken.lineNumber;

                // Then, I recursively parse the remaining part of the term.
                _term_();
            }

        } catch (CompilationException ce) {

            // I wrap and throw the exception with context for the term.
            throw new CompilationException("Syntax Error when parsing (Term) -> Expected {<Factor> | <Term> * <Factor> | <Term> / <Factor> | <Term> % <Factor>} on line: " + lineNo, ce);
        }

        // Finally, I log the end of <Term>.
        myGenerate.finishNonterminal("Term");
    }

    /**
     * The logic is to parse the <Factor> nonterminal.
     * Grammar: <Factor> ::= identifier | numberConstant | ( <Expression> )
     *
     * It accepts an identifier or a number constant directly. If a left parenthesis is encountered,
     * it parses an enclosed expression and then expects a matching right parenthesis.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _factor_() throws IOException, CompilationException {

        // I record the current line number.
        int lineNo = nextToken.lineNumber;

        // I log the start of <Factor>.
        myGenerate.commenceNonterminal("Factor");

        try{
            switch (nextToken.symbol) {

                // I accept the token if it is an identifier or a number constant.
                case Token.identifier:
                case Token.numberConstant:
                    acceptTerminal(nextToken.symbol);
                    break;
    
                case Token.leftParenthesis:

                    // I accept the left parenthesis and then parse the enclosed expression.
                    acceptTerminal(Token.leftParenthesis);
                    _expression_();

                    // I check for the matching right parenthesis.
                    if (nextToken.symbol == Token.rightParenthesis) {

                        // I then accept the matching right parenthesis.
                        acceptTerminal(Token.rightParenthesis);
                    } else {

                        // Otherwise I report an error because the closing parenthesis is missing.
                        myGenerate.reportError(nextToken, "Missing closing parenthesis ')'.");
                    }
                    break;
    
                default:
                    // I report an error because an identifier, number constant, or a parenthesized expression is expected.
                    myGenerate.reportError(nextToken, "Expected an identifier, number constant, or '('expression')'.");
                    break;
            }
        }catch(CompilationException ce){

            // Then, I wrap and throw the exception with context for factor parsing.
            throw new CompilationException("Syntax Error when parsing (Factor) -> Expected {identifier | numberConstant | ( <Expression> ) } on line: " + lineNo, ce);
        }

        // Lastly, I log the end of <Factor>.
        myGenerate.finishNonterminal("Factor");
    }

    /**
     * The plan is to parse the <Condition> nonterminal.
     * Grammar: <Condition> ::= identifier <ConditionalOperator> identifier |
                identifier <ConditionalOperator> numberConstant |
                identifier <ConditionalOperator> stringConstant
     *
     * We start by accepting an identifier, then parse a conditional operator, and finally
     * accept an identifier, number constant, or string constant as the right-hand side.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _condition_() throws IOException, CompilationException {

        // We start by capturing the current line number.
        int lineNo = nextToken.lineNumber;

        // Log the start of <Condition>.
        myGenerate.commenceNonterminal("Condition");

        try {

            // Then we accept the first identifier in the condition.
            acceptTerminal(Token.identifier);

            // Update the line number after the identifier.
            lineNo = nextToken.lineNumber;

            // Parse the conditional operator.
            _conditionalOperator_();

            // We update the line number after the operator.
            lineNo = nextToken.lineNumber;

            // We check for the right-hand side of the condition.
            if (nextToken.symbol == Token.identifier
                    || nextToken.symbol == Token.numberConstant
                    || nextToken.symbol == Token.stringConstant) {
                
                // Accept the right-hand side of the condition.
                acceptTerminal(nextToken.symbol);

                // And update the line number after the right-hand side.
                lineNo = nextToken.lineNumber;
            } else {

                // If by any chance the right hand side of the condition is missing, I report an error.
                myGenerate.reportError(nextToken, "Expected an identifier, number, or string in condition.");
            }
        } catch (CompilationException ce) {

            // Then, I wrap and throw the exception with context for the condition.
            throw new CompilationException("Syntax Error when parsing (Condition) -> Expected {identifier <ConditionalOperator> identifier | numberConstant | stringConstant} on line: " + lineNo, ce);
        }

        // Finally, I log the end of <Condition>.
        myGenerate.finishNonterminal("Condition");
    }

    /**
     * Similarly, all the above, the plan is to parse the <ConditionalOperator> nonterminal.
     * Grammar: <ConditionalOperator> ::= > | >= | = | != | < | <=
     *
     * We check if whether the current token is one of the valid conditional operators and accept it.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _conditionalOperator_() throws IOException, CompilationException {

        // We start by saving the current line number.
        int lineNo = nextToken.lineNumber;

        // Then log the start of <ConditionalOperator>.
        myGenerate.commenceNonterminal("ConditionalOperator");

        try{

            // We check for operators.
            switch (nextToken.symbol) {
                case Token.equalSymbol:
                case Token.notEqualSymbol:
                case Token.lessThanSymbol:
                case Token.lessEqualSymbol:
                case Token.greaterThanSymbol:
                case Token.greaterEqualSymbol:

                    // We then accept the operator if it matches one of the expected ones.
                    acceptTerminal(nextToken.symbol);
                    break;
                default:
                    // If none matches, I report an error because a valid conditional operator was expected.
                    myGenerate.reportError(nextToken, "Expected a conditional operator.");
            }
        }catch(CompilationException ce){

            // I wrap and throw the exception with context for the conditional operator.
            throw new CompilationException("Syntax Error when parsing (ConditionalOperator) -> Expected {= | != | < | <= | > | >=} on line: " + lineNo, ce);
        }
        
        // Finally, we log the end of <ConditionalOperator>.
        myGenerate.finishNonterminal("ConditionalOperator");
    }

    /**
     * The plan is to parse the <ArgumentList> nonterminal.
     * Grammar: <ArgumentList> ::= identifier | <ArgumentList> , identifier
     *
     * It is designed to expect at least one identifier and then recursively processes additional identifiers
     * separated by commas.
     *
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if a syntax error is detected.
     */

    private void _argumentList_() throws IOException, CompilationException {

        // We start by capturing the current line number.
        int lineNo = nextToken.lineNumber;

        // Log the start of <ArgumentList>.
        myGenerate.commenceNonterminal("ArgumentList");

        try {

            // We process the first argument, which must be an identifier.
            for (int i = 0; i < 1; i++) {
                if (nextToken.symbol == Token.identifier) {
                    acceptTerminal(Token.identifier);

                    // Then update the line number after the identifier.
                    lineNo = nextToken.lineNumber;
                } else {

                    // Else, I report an error because a variable in the argument list was expected.
                    myGenerate.reportError(nextToken, "Expected a variable in the argument list.");
                    return;
                }
            }

            // I process additional arguments if a comma is found.
            while (nextToken.symbol == Token.commaSymbol) {
                acceptTerminal(Token.commaSymbol);

                // Update the line number after the comma.
                lineNo = nextToken.lineNumber;

                // Then, I recursively process the next argument.
                _argumentList_();
            }

        } catch (CompilationException ce) {
            
            // We wrap and throw the exception with context for the argument list.
            throw new CompilationException("Syntax Error when parsing (ArgumentList) -> Expected {identifier | <ArgumentList>, identifier} on line: " + lineNo, ce);
        }

        // Finally, we log the end of <ArgumentList>.
        myGenerate.finishNonterminal("ArgumentList");
    }

    /**
     * We verify that the current token matches the expected terminal.
     * If the token is correct, it is inserted into the trace and the next token is retrieved.
     * If the token does not match, an error is reported.
     *
     * @param symbol the expected token symbol.
     * @throws IOException if an I/O error occurs.
     * @throws CompilationException if the token does not match the expected symbol.
     */

    @Override
    public void acceptTerminal(int symbol) throws IOException, CompilationException {

        // We start by checking if the current token's symbol matches the expected symbol.
        if (nextToken.symbol == symbol) {

            // Log the accepted terminal.
            myGenerate.insertTerminal(nextToken);

            // Then get the next token from the lexical analyser.
            nextToken = lex.getNextToken();
        } else {

            // Else, we report an error specifying the expected token.
            myGenerate.reportError(nextToken, "Expected " + Token.getName(symbol));
        }
    }
}
